def _use_color():
    if os.environ.get("FORCE_COLOR"):
        return True
    if os.environ.get("NO_COLOR"):
        return False
    try:
        return sys.stdout.isatty()
    except (OSError, ValueError):
        return False


_COLOR = _use_color()


def _paint(code, text):
    return f"\x1b[{code}m{text}\x1b[0m" if _COLOR else text


def _tag(status):
    if status == "PASS":
        return _paint("32", "[PASS]")
    if status in ("FAIL", "TIMEOUT"):
        return _paint("31", f"[{status}]")
    return f"[{status}]"


_WIN_FATAL = {
    0xC0000005: "ACCESS_VIOLATION",
    0xC00000FD: "STACK_OVERFLOW",
    0xC0000094: "INT_DIVIDE_BY_ZERO",
}


def _crash_name(returncode):
    """Name a fatal exit code, or None if the process exited normally."""
    if returncode < 0:
        try:
            return signal.Signals(-returncode).name
        except ValueError:
            return f"signal {-returncode}"
    if returncode >= 0xC0000000:
        return _WIN_FATAL.get(returncode, f"NTSTATUS 0x{returncode:08X}")
    return None


def _print_diff(diff_text):
    for line in diff_text.splitlines():
        stripped = line.lstrip()
        if stripped.startswith("-"):
            print(_paint("31", line))
        elif stripped.startswith("+"):
            print(_paint("32", line))
        elif stripped.startswith("@@"):
            print(_paint("36", line))
        else:
            print(line)


