def run_one(name, case_dir, compiler, use_valgrind, timeout, log_dir):
    source, expected_out, expected_exit = read_case(case_dir)
    failure_indices = []
    leak_failures = []
    failure_index = 1

    while True:
        command = [
            compiler,
            "--debugForceNthMallocFail",
            str(failure_index),
        ]
        log_path = None
        if use_valgrind:
            log_path = os.path.join(
                log_dir, f"{name}.malloc-{failure_index}.valgrind.log"
            )
            command = (
                # AI generated by: Codex / GPT-6
                # Prompt: "When running valgrind, it fails on illegal instruction on cachyos, therefore not checking the memory leaks. Can you have a look into that?"
                # Changes: Allow a local Valgrind executable override without changing shared defaults.
                [VALGRIND_BIN] + VALGRIND_FLAGS + ["--log-file=" + log_path] + command
            )
        try:
            proc = subprocess.run(
                command,
                input=source,
                capture_output=True,
                timeout=timeout,
                check=False,
            )
        except subprocess.TimeoutExpired:
            details = f"timed out after {timeout}s at allocation index {failure_index}"
            if failure_indices:
                details += f" (prior injected failures: {', '.join(map(str, failure_indices))})"
            return {
                "name": name,
                "status": "FAIL",
                "leaked": bool(leak_failures),
                "info": details,
                "diff": "",
            }

        actual_exit = proc.returncode
        actual_out = proc.stdout or b""
        actual_err = proc.stderr or b""
        forced_allocation_failure = b"(forced allocation failure)" in actual_err and (
            actual_exit == INTERNAL_ERROR_EXIT
            or (use_valgrind and actual_exit == VALGRIND_ERROR_EXIT)
        )

        if use_valgrind:
            leak_bytes, detail = parse_valgrind_log(log_path)
            if leak_bytes is None:
                leak_failures.append(f"index {failure_index}: {detail}")
            elif leak_bytes > 0:
                leak_failures.append(f"index {failure_index}: {leak_bytes}B ({detail})")
            if actual_exit == VALGRIND_ERROR_EXIT and leak_bytes == 0:
                leak_failures.append(f"index {failure_index}: valgrind reported errors")

        if forced_allocation_failure:
            failure_indices.append(failure_index)
            failure_index += 1
            continue

        exit_ok = actual_exit == expected_exit
        if use_valgrind and actual_exit == VALGRIND_ERROR_EXIT:
            # Valgrind masks the child exit code when it reports an error.
            exit_ok = True
        out_ok = actual_out == expected_out
        leaked = bool(leak_failures)
        status = "FAIL" if leaked or not exit_ok or not out_ok else "PASS"
        info = (
            f"exit {actual_exit} (want {expected_exit}), "
            f"{len(actual_out)}/{len(expected_out)} output bytes"
        )
        crash = _crash_name(actual_exit)
        if crash is not None:
            info = f"crashed ({crash}), " + info
        if failure_indices:
            info += ", forced allocation failures at indices " + ", ".join(
                map(str, failure_indices)
            )
        if use_valgrind:
            info += ", leaks: " + ("; ".join(leak_failures) if leaked else "none")
        diff = (
            text_diff(expected_out, actual_out)
            if status == "FAIL" and not out_ok
            else ""
        )
        return {
            "name": name,
            "status": status,
            "leaked": leaked,
            "info": info,
            "diff": diff,
        }


def main(argv=None):
    parser = argparse.ArgumentParser(description="Run compiler e2e cases.")
